function createStore(initialValue) {
  let state = initialValue;
  const listeners = [];

  function subscribe(listener) {
    listeners.push(listener);
  }

  function setState(newValue) {
    state = newValue;

    listeners.forEach((listener) => {
      listener(state);
    });
  }

  function getState() {
    return state;
  }

  return {
    subscribe,
    setState,
    getState
  };
}

