class TaskQueue {
  constructor() {
    this.queue = [];
  }

  add(task) {
    this.queue.push(task);
  }

  process() {
    while (this.queue.length > 0) {
      const currentTask = this.queue.shift();

      currentTask();
    }
  }
}

